// FSN host entry, generated by @fsn.dev/adapter-sveltekit.
// Default export: { fetch(request: Request): Promise<Response> }.

import { createReadStream } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { extname } from 'node:path';
import { Readable } from 'node:stream';
import { Server } from 'SERVER';
import { manifest } from 'MANIFEST';

const BASE = __FSN_BASE__;
/** @type {Map<string, string>} URL pathname → file relative to this module. */
const STATICS = new Map(__FSN_STATICS__);
/** @type {Set<string>} Prerendered page pathnames. */
const PAGES = new Set(__FSN_PAGES__);

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.avif': 'image/avif',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.wasm': 'application/wasm',
  '.pdf': 'application/pdf',
  '.mp3': 'audio/mpeg',
  '.wav': 'audio/wav',
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
  ...manifest.mimeTypes,
};

const IMMUTABLE_PREFIX = `${BASE}/${manifest.appPath}/immutable/`;

const fileURL = (path) => new URL(`./${path}`, import.meta.url);

const server = new Server(manifest);
await server.init({
  env: process.env,
  read: (file) => Readable.toWeb(createReadStream(fileURL(`client/${file}`))),
});

/**
 * @param {string} pathname
 * @param {string} file
 * @param {boolean} head
 */
async function serveStatic(pathname, file, head) {
  const body = await readFile(fileURL(file));
  const headers = new Headers({
    'content-type': MIME_TYPES[extname(file).toLowerCase()] ?? 'application/octet-stream',
    'content-length': String(body.byteLength),
  });
  if (pathname.startsWith(IMMUTABLE_PREFIX)) {
    headers.set('cache-control', 'public, max-age=31536000, immutable');
  }
  return new Response(head ? null : body, { status: 200, headers });
}

export default {
  /** @param {Request} request */
  async fetch(request) {
    if (request.method === 'GET' || request.method === 'HEAD') {
      const url = new URL(request.url);
      let pathname = url.pathname;
      try {
        pathname = decodeURIComponent(pathname);
      } catch {
        // malformed escapes: fall through with the raw pathname
      }

      const file = STATICS.get(pathname);
      if (file) return serveStatic(pathname, file, request.method === 'HEAD');

      // Match SvelteKit's trailingSlash handling for prerendered pages.
      const alternate = pathname.endsWith('/') ? pathname.slice(0, -1) : pathname + '/';
      if (PAGES.has(alternate)) {
        return new Response(null, { status: 308, headers: { location: alternate + url.search } });
      }
    }

    return server.respond(request, {
      getClientAddress: () => '127.0.0.1',
      platform: {},
    });
  },
};
